<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <main id="maincontent" class="page-shell" tabindex="-1">
    <section class="hero" aria-labelledby="support-heading">
      <div>
        <span class="eyebrow">Support</span>
        <h1 id="support-heading">Get help from our support team</h1>
      </div>
      <p>
        Share your details and we will follow up with the right specialist. Required
        fields are marked with <span aria-hidden="true">*</span><span class="sr-only"> an asterisk</span>.
      </p>
    </section>

    <section class="support-layout">
      <div class="contact-card">
        <h2 class="card-title">Contact support</h2>
        <p class="card-copy">
          Tell us how to reach you and we will get back to you as quickly as possible.
        </p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              autocomplete="name"
              required
              aria-required="true"
              aria-describedby="full-name-error"
              aria-errormessage="full-name-error"
              placeholder="Jordan Lee"
            >
            <p id="full-name-error" class="field-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="email-address"
              name="email-address"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-required="true"
              aria-describedby="email-address-error"
              aria-errormessage="email-address-error"
              placeholder="name@example.com"
            >
            <p id="email-address-error" class="field-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number <span class="field-note">(optional)</span></label>
            <input
              id="phone-number"
              name="phone-number"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-number-help phone-number-error"
              aria-errormessage="phone-number-error"
              placeholder="+1 555 123 4567"
            >
            <p id="phone-number-help" class="field-help">Expected format: +1 555 123 4567.</p>
            <p id="phone-number-error" class="field-error" aria-live="polite"></p>
          </div>

          <div class="actions">
            <button type="submit">Send request</button>
            <p id="form-status" class="status-message" aria-live="polite"></p>
          </div>
        </form>
      </div>

      <aside class="info-card" aria-labelledby="support-expectations">
        <h2 id="support-expectations" class="card-title">What to expect</h2>
        <p class="card-copy">A support specialist will review your request and contact you using your preferred details.</p>
        <ul>
          <li>Required details are used to identify your request and reply.</li>
          <li>Phone number is optional and helps if you prefer a callback.</li>
          <li>Inline guidance appears next to each field if something needs attention.</li>
        </ul>
      </aside>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const statusMessage = document.getElementById('form-status');

    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Error: Enter your full name.';
          }

          if (value.trim().length < 2) {
            return 'Error: Enter your full name using at least 2 characters.';
          }

          return '';
        }
      },
      email: {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Error: Enter your email address.';
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return 'Error: Enter a valid email address like name@example.com.';
          }

          return '';
        }
      },
      phone: {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return '';
          }

          const digitsOnly = trimmed.replace(/\D/g, '');
          const phonePattern = /^\+?[\d()\s-]+$/;
          if (!phonePattern.test(trimmed) || digitsOnly.length < 10 || digitsOnly.length > 15) {
            return 'Error: Enter a phone number in the format +1 555 123 4567.';
          }

          return '';
        }
      }
    };

    function setFieldState(field, message) {
      field.error.textContent = message;

      if (message) {
        field.input.setAttribute('aria-invalid', 'true');
      } else {
        field.input.removeAttribute('aria-invalid');
      }
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldState(field, message);
      return message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener('blur', () => {
        validateField(field);
      });

      field.input.addEventListener('input', () => {
        if (field.error.textContent) {
          validateField(field);
        }

        statusMessage.textContent = '';
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      statusMessage.textContent = '';

      const invalidMessages = Object.values(fields).map((field) => ({
        field,
        message: validateField(field)
      }));

      const firstInvalid = invalidMessages.find((item) => item.message);
      if (firstInvalid) {
        firstInvalid.field.input.focus();
        return;
      }

      statusMessage.textContent = 'Thanks. Your support request is ready to be reviewed.';
      form.reset();
      Object.values(fields).forEach((field) => setFieldState(field, ''));
    });
  </script>
